package com.chatsystem.admin.controller;
import com.chatsystem.admin.navigation.*;import com.chatsystem.admin.ui.DisabledControlSupport;import com.chatsystem.admin.ui.cell.AdminMemberCell;import com.chatsystem.shared.model.*;import com.chatsystem.shared.service.AdminService;import javafx.collections.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.StackPane;import java.util.*;
public final class GroupDetailsController{
 private final AdminService service;private final AdminNavigator navigator;private final ObservableList<ConversationMember> members=FXCollections.observableArrayList();private long id;@FXML private Label nameLabel,descriptionLabel;@FXML private Button backButton,moderationButton,exportButton;@FXML private StackPane exportWrapper;@FXML private ListView<ConversationMember> memberList;
 public GroupDetailsController(AdminService s,AdminNavigator n){service=s;navigator=n;}@FXML private void initialize(){backButton.setOnAction(e->navigator.navigate(ViewRequest.of(AdminRoute.GROUPS)));moderationButton.setOnAction(e->openModerationHistory());memberList.setItems(members);memberList.setCellFactory(v->new AdminMemberCell(service));DisabledControlSupport.install(exportButton,exportWrapper,exportReason());}
 public void present(long groupId){id=groupId;Conversation g=service.getGroup(id).orElseThrow(()->new IllegalArgumentException("Unknown group "+id));members.setAll(service.getGroupMembers(id));if(nameLabel!=null){nameLabel.setText(g.getName());descriptionLabel.setText(g.getDescription());}}
 public ObservableList<ConversationMember> members(){return FXCollections.unmodifiableObservableList(members);}public void openModerationHistory(){navigator.showModerationForGroup(id);}public String exportReason(){return "Group member export is unavailable in the frontend-only demo.";}
}
